mapper.update:
UPDATE export_job
SET status       = 'done',
    completed_at = now(),
    last_error   = null
WHERE checkpoint_date = #{transactionDate}
  AND corporate_number = #{corporateNumber}
  AND claimed_by = #{workerId}

UPDATE export_job
SET status     = 'failed',
    last_error = #{error}
WHERE checkpoint_date = #{transactionDate}
  AND corporate_number = #{corporateNumber}
  AND claimed_by = #{workerId}
